    stack = []
    matching_brackets = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_brackets.values():
            stack.append(char)
        elif char in matching_brackets.keys():
            if not stack or stack.pop() != matching_brackets[char]:
                return False
        else:
            # If the character is not a bracket, it's invalid
            return False

    return len(stack) == 0
