    if lo > hi:
        return 0

    # Use the formula for counting set bits in a range
    def count_set_bits(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Calculate the total number of set bits from 0 to hi
    total_set_bits = sum(count_set_bits(i) for i in range(hi + 1))

    # Calculate the total number of set bits from 0 to lo - 1
    if lo > 0:
        total_set_bits -= sum(count_set_bits(i) for i in range(lo))

    return total_set_bits

