from collections import *

def count_subsequence_matches(text: str, sub: str) -> int:
    if not sub:
        return 0

    n = len(text)
    m = len(sub)

    # Initialize a DP table where dp[i][j] will store the number of matches ending at index i in text and j in sub
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There is one match of an empty substring
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if text[i - 1] == sub[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    # The answer is the number of matches ending at the last character of text
    return dp[n][m]
```

