import xml.etree.ElementTree as ET

def count_items(xml_text: str) -> int:
    root = ET.fromstring(xml_text)
    item_count = 0

    def traverse(element):
        nonlocal item_count
        if element.tag == 'item':
            item_count += 1
        for child in element:
            traverse(child)

    traverse(root)
    return item_count

