from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def bfs(start):
        queue = [(start, 1)]
        visited = set()
        visited.add(start)

        while queue:
            node, path_length = queue.pop(0)
            if node == target:
                return path_length

            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path_length + 1))

        return float('inf')

    shortest_path_length = bfs(source)
    if shortest_path_length == float('inf'):
        return 0

    # Calculate the number of shortest paths
    def count_paths(node, path_length):
        if node == target and path_length == shortest_path_length:
            return 1
        if path_length > shortest_path_length:
            return 0

        count = 0
        for neighbor in graph[node]:
            count += count_paths(neighbor, path_length + 1)

        return count

    return count_paths(source, 1)
