    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize queue for BFS
    queue = deque([(start, 0, False)])  # (position, steps, has_break)
    visited = set()

    while queue:
        pos, steps, has_break = queue.popleft()

        if pos == end:
            return steps

        if pos in visited:
