        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    queue = [(start, 0, False)]  # (position, steps, has_broken_wall)
    visited = set()

    while queue:
        pos, steps, has_broken_wall = queue.pop(0)

        if pos == end:
            return steps

