from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Create adjacency list representation of the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Initialize distances and visited status
    distances = [float('inf')] * n
    distances[source] = 0
    visited = [False] * n

    # Perform BFS to find shortest paths
    queue = [source]
    while queue:
        current = queue.pop(0)
        visited[current] = True

        for neighbor in graph[current]:
            if not visited[neighbor]:
                new_distance = distances[current] + 1
                if new_distance < distances[neighbor]:
                    distances[neighbor] = new_distance
                    queue.append(neighbor)

    # If target is unreachable or same as source, return appropriate value
    if distances[target] == float('inf'):
        return 0
    elif source == target:
        return 1

    # Count the number of shortest paths to the target
    count = 0
    for i in range(n):
        if distances[i] == distances[target]:
            count += 1

    return count

