    if n == 0:
        return 1

    blocked_set = set(blocked)

    def is_valid(row: int, col: int) -> bool:
        for r, c in blocked_set:
            if r == row or c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_valid(row, col):
                blocked_set.add((row, col))
                count += backtrack(row + 1)
                blocked_set.remove((row, col))

        return count

    return backtrack(0)

