from collections import deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build the adjacency list representation of the graph
    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize the queue for BFS and visited set
    queue = deque([(source, 1)])
    visited = {source}

    # Dictionary to store the number of shortest paths to each node
    path_count = {source: 1}

    while queue:
        current_node, path_length = queue.popleft()

        # If we reach the target, check if it's the first shortest path found
        if current_node == target:
            return path_count[target]

        # Explore neighbors
        for neighbor in adj_list[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                path_count[neighbor] = path_count[current_node]
                queue.append((neighbor, path_length + 1))

    # If target is not reachable, return 0
    return 0
