from math import gcd, lcm
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def chinese_remainder_theorem(moduli, remainders):
        M = reduce(lcm, moduli)
        result = 0
        for m, r in zip(moduli, remainders):
            Mi = M // m
            gcd_m, x, _ = extended_gcd(m, Mi)
            if gcd_m != 1:
                raise ValueError("Moduli are not coprime")
            result += r * x * Mi
        return result % M

    moduli = [m for _, m in congruences]
    remainders = [r % m for r, m in congruences]

    try:
        x = chinese_remainder_theorem(moduli, remainders)
        L = reduce(lcm, moduli)
        return (x, L)
    except ValueError:
        return None
