from typing import List

def subsets_with_sum(nums: List[int], k: int) -> List[List[int]]:
    def backtrack(start, path):
        if sum(path) == k:
            result.append(sorted(path))
            return
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue
            path.append(nums[i])
            backtrack(i + 1, path)
            path.pop()

    result = []
    nums.sort()
    backtrack(0, [])
    return result

