def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    m, n = len(source), len(target)

    # Initialize a 2D array to store the edit costs
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j * insert_cost  # Insert all characters from target
            elif j == 0:
                dp[i][j] = i * delete_cost  # Delete all characters from source
            else:
                if source[i - 1] == target[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]  # No cost for matching characters
                else:
                    dp[i][j] = min(
                        dp[i - 1][j] + delete_cost,  # Delete from source
                        dp[i][j - 1] + insert_cost,  # Insert into target
                        dp[i - 1][j - 1] + replace_cost  # Replace character
                    )

    return dp[m][n]
