def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        return ""

    is_negative = number.startswith('-')
    number = number.lstrip('-')

    if not all(c.isalnum() for c in number):
        raise ValueError("Number contains invalid characters.")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"

    if from_base == 10:
        if is_negative:
            return '-' + digits[int(number) % to_base]
        else:
            return digits[int(number)]

    try:
        decimal_value = int(number, from_base)
    except ValueError:
        raise ValueError("Invalid number format.")

    if is_negative:
        return '-' + digits[decimal_value % to_base] + digits[:decimal_value // to_base][::-1]
    else:
        return digits[decimal_value % to_base] + digits[:decimal_value // to_base][::-1]

