def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        return "0"

    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    if not all(c.isalnum() and c.lower() in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid characters in number.")

    # Convert from base to decimal
    decimal_value = 0
    power = 0
    for char in reversed(number):
        digit = ord(char.lower()) - ord('0')
        if digit >= from_base:
            raise ValueError(f"Digit {char} is not valid in base {from_base}.")
        decimal_value += digit * (from_base ** power)
        power += 1

    # Convert from decimal to base
    if decimal_value == 0:
        return "0"

    result = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result.append(chr(ord('0') + remainder))
        decimal_value //= to_base

    if negative:
        result.append('-')

    return ''.join(reversed(result))

