import re

def matches_filter(expression: str, record: dict) -> bool:
    # Define a regular expression pattern to match valid keys in the record
    key_pattern = re.compile(r'\b\w+\b')

    # Check if the expression contains only valid keys
    if not key_pattern.fullmatch(expression):
        raise ValueError("Invalid filter expression")

    # Evaluate the expression using eval with a restricted context
    try:
        # Create a dictionary with only the keys from the record
        filtered_record = {k: record[k] for k in key_pattern.findall(expression)}

        # Use eval with a restricted context to evaluate the expression
        return eval(expression, {'__builtins__': None}, filtered_record)
    except Exception as e:
        raise ValueError(f"Error evaluating filter expression: {e}")

