            if assigned_slots[slot] is None:
                assigned_slots[slot] = name
                break

    # Collect the names of jobs assigned to each slot
    result = []
    for slot in range(len(assigned_slots)):
        if assigned_slots[slot] is not None:
            result.append(f"{slot + 1}: {assigned_slots[slot]}")

    return result

