from typing import *
from collections import defaultdict

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_cost = float('inf')
    best_path = None

    def dfs(node, current_path, current_cost):
        nonlocal min_cost, best_path

        if node == goal:
            if current_cost < min_cost or (current_cost == min_cost and current_path < best_path):
                min_cost = current_cost
                best_path = current_path[:]
            return

        for neighbor, weight in graph[node]:
            if neighbor not in current_path:
                current_path.append(neighbor)
                dfs(neighbor, current_path, current_cost + weight)
                current_path.pop()

    dfs(start, [start], 0)

    return (min_cost, best_path) if best_path else None
