from collections import defaultdict, deque

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    # Build the graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Priority queue for Dijkstra's algorithm
    pq = [(0, start, [start])]
    visited = set()

    while pq:
        current_cost, current_node, path = heapq.heappop(pq)

        if current_node == goal:
            return (current_cost, path)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            new_cost = current_cost + weight
            new_path = path + [neighbor]

            # Use lexicographical order for ties
            if neighbor not in visited or new_cost < current_cost or (new_cost == current_cost and new_path < path):
                heapq.heappush(pq, (new_cost, neighbor, new_path))

    return None
