        if field.startswith('"'):
            # Handle quoted fields
            result = []
            i = 1
            while i < len(field):
                if field[i] == '"':
                    # Escape double quote
                    if i + 1 < len(field) and field[i + 1] == '"':
                        result.append('"')
                        i += 2
                    else:
                        break
                elif field[i] == ',':
                    # End of quoted field
                    break
