def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Optional[Tuple[int, List[str]]]:
    if start == goal:
        return (0, [start])

    # Build the adjacency list representation of the graph
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Priority queue to store (cost, path) tuples
    pq = [(0, [start])]
    visited = set()

    while pq:
        current_cost, current_path = heapq.heappop(pq)

        # If we reach the goal, return the result
        if current_path[-1] == goal:
            return (current_cost, current_path)

        # If we've already visited this state, skip it
        if tuple(current_path) in visited:
            continue

        visited.add(tuple(current_path))

        # Explore neighbors
        for neighbor, weight in graph[current_path[-1]]:
            new_path = current_path + [neighbor]
            new_cost = current_cost + weight
            heapq.heappush(pq, (new_cost, new_path))

    # If no path is found, return None
    return None
