        if not tokens:
            return None
        token = tokens.pop(0)
        if token == '(':
            expr = parse_expression(tokens)
            if tokens.pop(0) != ')':
                raise ValueError("Unmatched parenthesis")
            return expr
        elif token.isdigit() or '.' in token:
            return float(token)
        elif token in ['+', '-', '*', '/', '**', 'sqrt', 'abs', 'sin', 'cos']:
