def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Optional[Tuple[int, List[str]]]:
    if start == goal:
        return (0, [start])

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = {}
        if v not in graph:
            graph[v] = {}
        graph[u][v] = w
        graph[v][u] = w

    priority_queue = [(0, [start])]
    visited = set()

    while priority_queue:
        current_cost, path = heapq.heappop(priority_queue)

        if path[-1] == goal:
            return (current_cost, path)

        if path[-1] in visited:
            continue

        visited.add(path[-1])

        for neighbor, weight in graph[path[-1]].items():
            if neighbor not in visited:
                new_path = path + [neighbor]
                new_cost = current_cost + weight
                heapq.heappush(priority_queue, (new_cost, new_path))

