import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_field(field):
        if field.startswith('"'):
            # Handle quoted fields
            field = field[1:]
            while field:
                match = re.match(r'"([^"]*)"', field)
                if match:
                    field = match.group(1)
                    break
                else:
                    field = field[1:]
            return field
        else:
            # Handle unquoted fields
            return field.split(',')

    records = []
    current_record = []
    lines = text.strip().split('\n')

    for line in lines:
        fields = parse_field(line)
        current_record.extend(fields)

        # Check if the line ends with a comma or is the last line
        if line.endswith(',') or line == '':
            records.append(current_record)
            current_record = []

    return records
