def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        elif source[i].isdigit():
            start = i
            while i < len(source) and source[i].isdigit():
                i += 1
            tokens.append(("NUMBER", source[start:i]))
        elif source[i] == '.':
            if i + 1 < len(source) and source[i + 1].isdigit():
                start = i
                i += 1
                while i < len(source) and source[i].isdigit():
                    i += 1
                tokens.append(("NUMBER", source[start:i]))
            else:
                raise ValueError(f"Invalid number format at position {i}")
        elif source[i].isalpha() or source[i] == '_':
            start = i
            while i < len(source) and (source[i].isalnum() or source[i] == '_'):
                i += 1
            tokens.append(("NAME", source[start:i]))
        elif source[i] in "+-*/<=>=":
            if i + 1 < len(source) and source[i + 1] in "+-*/<=>=":
                raise ValueError(f"Invalid operator at position {i}")
            tokens.append(("OP", source[i]))
