import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'https://'
    if not url.startswith('https://'):
        return False

    # Remove the 'user@' or 'user:password@' prefix if present
    user_info_end = url.find('@')
    if user_info_end != -1:
        url = url[user_info_end + 1:]

    # Remove the trailing '.' from the host if present
    host = url.split('/')[2]
    if host.endswith('.'):
        host = host[:-1]

    # Split the host into labels
    labels = host.split('.')

    # Check if there are at least two labels
    if len(labels) < 2:
        return False

    # Check if each label is valid
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if the last label consists only of letters
    if not labels[-1].isalpha():
        return False

    # Check if the host is not 'localhost' and does not end with '.localhost'
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check if the port is either absent or 443
    port = None
    try:
        port = int(url.split('/')[3])
    except ValueError:
        pass
    if port is not None and port != 443:
        return False

    return True
