import re

def evaluate_expression(expr: str) -> int:
    def parse_number(s):
        if s.startswith('-'):
            return -int(s[1:])
        return int(s)

    def precedence(op):
        if op in ('^', '*'):
            return 2
        elif op in ('+', '-'):
            return 1
        elif op == '(':
            return 0
        return -1

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left // right)
        elif operator == '^':
            values.append(left ** right)

    def evaluate(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
                values.append(parse_number(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            else:
                while (operators and operators[-1] != '(' and
                       precedence(operators[-1]) >= precedence(token)):
                    apply_operator(operators, values)
                operators.append(token)
            i += 1
        while operators:
            apply_operator(operators, values)
        return values[0]

    tokens = re.findall(r'\d+|\+|-|\*|\/|\^|\(|\)', expr)
    return evaluate(tokens)

# Example usage:
print(evaluate_expression("2^3^2"))  # Output: 512
print(evaluate_expression("-2^2"))  # Output: -4
print(evaluate_expression("7/-2"))   # Output: -3
print(evaluate_expression("3*(4+5)"))  # Output: 27
print(evaluate_expression("10/2+3"))  # Output: 8
```

