    def parse_number(s):
        if s.startswith('-'):
            return -int(s[1:])
        return int(s)

    def parse_expr(i):
        stack = []
        while i < len(expr):
            if expr[i] == ' ':
                i += 1
                continue
            elif expr[i] == '(':
                j = parse_expr(i + 1)
                stack.append(j)
                i = j + 1
            elif expr[i] in '+-*/^':
                op = expr[i]
                i += 1
                if op == '^':
                    while i < len(expr) and expr[i] == '^':
                        i += 1
                    num = parse_expr(i)
                    stack.append(num)
                    continue
                num = parse_number(expr[i:])
                if op == '-':
                    num = -num
                stack.append(num)
                while stack and stack[-1] in '+-*/^' and precedence(stack[-1]) >= precedence(op):
                    b = stack.pop()
                    c = stack.pop()
                    if stack and stack[-1] == '^':
                        c = stack.pop()
                        stack.append(c ** b)
                    elif stack and stack[-1] in '+-':
                        stack.append(c + b)
                    elif stack and stack[-1] in '*':
                        stack.append(c * b)
                    elif stack and stack[-1] == '/':
