        raise ValueError("Number of columns in the first matrix must match the number of rows in the second matrix.")

    m, k = len(a), len(a[0])
    n = len(b[0])

    result = [[0] * n for _ in range(m)]

    for i in range(m):
        for j in range(n):
            for l in range(k):
                result[i][j] += a[i][l] * b[l][j]

    return result

