def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    index = 0

    while index < len(program):
        command = program[index]

        if command == "PUSH":
            try:
                value = int(command.split()[1])
                stack.append(value)
            except ValueError:
                raise ValueError("Invalid number format for PUSH command")
        elif command == "POP":
            if not stack:
                raise ValueError("POP command on empty stack")
            stack.pop()
        elif command == "DUP":
            if not stack:
                raise ValueError("DUP command on empty stack")
            stack.append(stack[-1])
        elif command == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP command requires at least two elements on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif command.startswith("ADD"):
            if len(stack) < 2:
                raise ValueError("ADD command requires at least two elements on stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif command.startswith("SUB"):
            if len(stack) < 2:
                raise ValueError("SUB command requires at least two elements on stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif command.startswith("MUL"):
            if len(stack) < 2:
                raise ValueError("MUL command requires at least two elements on stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif command.startswith("JMP"):
            try:
                target = int(command.split()[1])
                if target < 0 or target >= len(program):
                    raise ValueError("JMP target out of range")
                index = target
            except ValueError:
                raise ValueError("Invalid target for JMP command")
        elif command.startswith("JZ"):
            try:
                target = int(command.split()[1])
                if target < 0 or target >= len(program):
                    raise ValueError("JZ target out of range")
                if stack and stack[-1] == 0:
                    index = target
                else:
                    index += 1
            except ValueError:
                raise ValueError("Invalid target for JZ command")
        elif command == "HALT":
            break
        else:
            raise ValueError(f"Unknown command: {command}")

        index += 1

    return stack
