from typing import *
from collections import *

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
        elif kind == 'order':
            while waiting and waiting[0][1] <= quantity:
                order_item, order_quantity = waiting.pop(0)
                stock[order_item] -= order_quantity
                quantity -= order_quantity
            if quantity > 0:
                waiting.append((item, quantity))

    return dict(stock), waiting
