def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    while ip < len(program):
        instruction = program[ip]
        if instruction.startswith('PUSH'):
            try:
                num = int(instruction.split()[1])
                stack.append(num)
            except ValueError:
                raise ValueError("Invalid number in PUSH instruction")
        elif instruction == 'POP':
            if not stack:
                raise ValueError("POP instruction on empty stack")
            stack.pop()
        elif instruction == 'DUP':
            if not stack:
                raise ValueError("DUP instruction on empty stack")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError("SWAP instruction requires at least two elements on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith('ADD'):
            if len(stack) < 2:
                raise ValueError("ADD instruction requires at least two elements on stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)
        elif instruction.startswith('SUB'):
            if len(stack) < 2:
                raise ValueError("SUB instruction requires at least two elements on stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif instruction.startswith('MUL'):
            if len(stack) < 2:
                raise ValueError("MUL instruction requires at least two elements on stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)
        elif instruction.startswith('JMP'):
            try:
                target = int(instruction.split()[1])
                if target < 0 or target >= len(program):
                    raise ValueError("JMP target out of range")
                ip = target
            except ValueError:
                raise ValueError("Invalid target for JMP instruction")
        elif instruction.startswith('JZ'):
            try:
                target = int(instruction.split()[1])
                if target < 0 or target >= len(program):
                    raise ValueError("JZ target out of range")
                if not stack:
                    raise ValueError("JZ instruction on empty stack")
                if stack.pop() == 0:
                    ip = target
                else:
                    ip += 1
            except ValueError:
                raise ValueError("Invalid target for JZ instruction")
        elif instruction == 'HALT':
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
        ip += 1
    return stack
