            if account in balances and amount > 0 and not balances[account] < amount + 2:
                final_balances[account] -= amount + 2
            else:
                failed.append(ops.index((op, *args)))
        elif op == 'transfer':
            source, target, amount = args
            if source != target and source in balances and target in balances and amount > 0 and not balances[source] < amount + 2:
                final_balances[source] -= amount + 2
                final_balances[target] += amount
            else:
                failed.append(ops.index((op, *args)))
        elif op == 'freeze':
            account = args[0]
            if account in balances:
                balances[account] = -balances[account]
        elif op == 'unfreeze':
            account = args[0]
            if account in balances:
                balances[account] = -balances[account]
        else:
