def weighted_harmonic_mean(vals: List[float], weights: List[float]) -> float:
    if not vals or len(vals) != len(weights):
        return 0.0

    total_weight = sum(weights)
    if total_weight == 0:
        return 0.0

    weighted_sum = sum(val * weight for val, weight in zip(vals, weights))
    harmonic_mean = len(vals) / (weighted_sum / total_weight)

