import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match valid tokens in the expression
    token_pattern = re.compile(r'\d+\.\d+|\d+|-|\+|\*|\/|\*\*|\(|\)')

    # Function to apply operator to two operands
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '**':
            values.append(left ** right)

    # Stack to hold operators
    operators = []
    # Stack to hold values
    values = []

    # Tokenize the expression
    tokens = token_pattern.findall(expression)

    # Iterate over tokens
    for token in tokens:
        if token.isdigit() or '.' in token:
            # Convert number token to float and push onto values stack
            values.append(float(token))
        elif token in ('+', '-', '*', '/', '**'):
            # Push operator onto operators stack
            while (operators and operators[-1] in ('*', '/', '**') and
                   precedence(operators[-1]) >= precedence(token)):
                apply_operator(operators, values)
            operators.append(token)
        elif token == '(':
            # Push opening parenthesis onto operators stack
            operators.append(token)
        elif token == ')':
            # Apply operators until an opening parenthesis is encountered
            while operators[-1] != '(':
                apply_operator(operators, values)
            # Pop the opening parenthesis
            operators.pop()

    # Apply remaining operators
    while operators:
        apply_operator(operators, values)

    # The final result should be the only value left in the values stack
    return values[0]

# Helper function to determine operator precedence
def precedence(op):
    if op in ('*', '/'):
        return 2
    elif op in ('+', '-'):
        return 1
    elif op == '**':
        return 3
    else:
        return 0
