        name = job.get('name', None)
        interval = job.get('interval', None)
        enabled = job.get('enabled', True)

        if not isinstance(name, str) or not isinstance(interval, int) or not isinstance(enabled, bool):
            raise ValueError("Job definition must contain 'name' (string), 'interval' (integer), and 'enabled' (boolean) keys.")

        parsed_jobs.append({'name': name, 'interval': interval, 'enabled': enabled})

    return parsed_jobs
