from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    def is_valid_position(row: int, col: int, blocked: List[Tuple[int, int]]) -> bool:
        for b_row, b_col in blocked:
            if b_row == row or b_col == col or abs(b_row - row) == abs(b_col - col):
                return False
        return True

    def backtrack(row: int, queens: List[int]) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_valid_position(row, col, blocked):
                queens[row] = col
                count += backtrack(row + 1, queens)
        return count

    queens = [-1] * n
    return backtrack(0, queens)
