def decode_runs(encoded: str) -> str:
    decoded = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            # Escape character
            decoded.append(encoded[i + 1])
            i += 2
        elif encoded[i] == '~':
            # Repeat character
            count = 0
            while i + 1 < len(encoded) and encoded[i + 1].isdigit():
                count = count * 10 + int(encoded[i + 1])
                i += 1
            decoded.extend([decoded[-1]] * count)
