def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    def topple(row, col):
        if grid[row][col] < 4:
            return
        grid[row][col] -= 4
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                grid[nr][nc] += 1

    while True:
        changed = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] >= 4:
                    topple(r, c)
                    changed = True
        if not changed:
            break

    return grid
