from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if not sizes:
        return []

    # Sort sizes in descending order
    sizes.sort(reverse=True)

    bins = []
    current_bin = []

    for size in sizes:
        if size > capacity:
            raise ValueError("Item size exceeds capacity")

        if not current_bin or sum(current_bin) + size <= capacity:
            current_bin.append(size)
        else:
            bins.append(current_bin)
            current_bin = [size]

    # Add the last bin if it's not empty
    if current_bin:
        bins.append(current_bin)

    return bins
