def matches_filter(expression: str, record: dict) -> bool:
    # Define a regular expression pattern for the filter expression
    pattern = r'^(?P<left>[^<>=!]+)(?P<op>[<>=!]+)(?P<right>[^<>=!]+)$'

    # Check if the expression matches the pattern
    match = re.match(pattern, expression)
    if not match:
        raise ValueError("Invalid filter expression")

    left, op, right = match.groups()

    # Convert left and right to float if they are numeric strings
    try:
        left = float(left)
        right = float(right)
    except ValueError:
        pass

    # Replace variable names with actual values from the record
    left_value = record.get(left)
    right_value = record.get(right)

    # Handle cases where either left or right is None
    if left_value is None or right_value is None:
        raise ValueError("Expression contains a non-existent key")

    # Evaluate the expression
    if op == '<':
        return left_value < right_value
    elif op == '<=':
        return left_value <= right_value
    elif op == '>':
        return left_value > right_value
    elif op == '>=':
        return left_value >= right_value
    elif op == '==':
        return left_value == right_value
    elif op == '!=':
        return left_value != right_value
    elif op == 'and':
        return left_value and right_value
    elif op == 'or':
        return left_value or right_value
    elif op == 'not':
        return not left_value
    else:
