import ast

def matches_filter(expression: str, record: dict) -> bool:
    try:
        # Parse the expression using Python's AST module
        tree = ast.parse(expression, mode='eval')

        # Define a visitor class to evaluate the AST
        class ExpressionEvaluator(ast.NodeVisitor):
            def visit_Name(self, node):
                # Check if the name is a key in the record
                if node.id in record:
                    return record[node.id]
                else:
                    raise ValueError(f"Invalid expression: '{node.id}' is not a key in the record")

            def visit_Num(self, node):
                # Return the numeric value
                return node.n

            def visit_Str(self, node):
                # Return the string value
                return node.s

            def visit_Compare(self, node):
                # Evaluate the comparison
                left = self.visit(node.left)
                right = self.visit(node.comparators[0])
                op = node.ops[0]
                if op.__class__ == ast.Eq:
                    return left == right
                elif op.__class__ == ast.NotEq:
                    return left != right
                elif op.__class__ == ast.Lt:
                    return left < right
                elif op.__class__ == ast.LtE:
                    return left <= right
                elif op.__class__ == ast.Gt:
                    return left > right
                elif op.__class__ == ast.GtE:
                    return left >= right
                else:
                    raise ValueError(f"Unsupported comparison operator: {op.__class__.__name__}")

