def convert_base(number: str, from_base: int, to_base: int) -> str:
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36")

    if not number:
        return "0"

    is_negative = number.startswith('-')
    number = number.lstrip('-')

    if not all(c.isalnum() and c.lower() in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid characters in number")

    if number == '0':
        return "0"

    # Convert from_base to decimal
    decimal_value = 0
    for i, char in enumerate(reversed(number)):
        digit = char.lower()
        if digit.isdigit():
            value = int(digit)
        else:
            value = ord(digit) - ord('a') + 10
        decimal_value += value * (from_base ** i)

    if is_negative:
        decimal_value = -decimal_value

    # Convert decimal to to_base
    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            result = str(remainder) + result
        else:
            result = chr(ord('a') + remainder - 10) + result
        decimal_value //= to_base

    return "-" + result if is_negative else result
