import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_field(field):
        if field.startswith('"'):
            # Handle quoted fields
            result = []
            i = 1
            while i < len(field):
                if field[i] == '"':
                    if i + 1 < len(field) and field[i + 1] == '"':
                        result.append('"')
                        i += 2
                    else:
                        break
                elif field[i] == ',':
                    result.append('".')
                    i += 1
                elif field[i] == '\n':
                    result.append('"\n')
                    i += 1
                else:
                    result.append(field[i])
                    i += 1
            return ''.join(result)
        else:
            # Handle unquoted fields
            return field

    # Split the text into lines
    lines = text.split('\n')

    # Parse each line into a list of fields
    records = []
    for line in lines:
        fields = re.split(r',(?=(?:[^"]*"[^"]*")*[^"]*$)', line)
        parsed_fields = [parse_field(field.strip()) for field in fields]
        records.append(parsed_fields)

    return records
