def evaluate_expression(expr: str) -> int:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left // right)
        elif operator == '^':
            values.append(left ** right)

    def get_next_token(expr, i):
        while i < len(expr) and expr[i].isspace():
            i += 1
        if i >= len(expr):
            return None, i
        if expr[i] in '0123456789':
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            return int(expr[i:j]), j
        if expr[i] in '+-*/^()':
            return expr[i], i + 1
        raise ValueError(f"Invalid character '{expr[i]}' at position {i}")

    def parse_expression(expr):
        operators = []
        values = []
        i = 0
        while i < len(expr):
            token, i = get_next_token(expr, i)
            if token is None:
                break
            if isinstance(token, int):
                values.append(token)
            elif token in '+-':
                while (operators and operators[-1] in '+-*/^' and
                       operators[-1] != '('):
                    apply_operator(operators, values)
                operators.append(token)
            elif token in '*/^':
                while (operators and operators[-1] in '+-*/^' and
                       operators[-1] != '(' and
                       precedence[token] <= precedence[operators[-1]]):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                if operators and operators[-1] == '(':
                    operators.pop()
                else:
                    raise ValueError("Unmatched parenthesis")
        while operators:
            apply_operator(operators, values)
        return values[0]

    precedence = {'^': 3, '+': 2, '-': 2, '*': 1, '/': 1}
    return parse_expression(expr.replace(' ', ''))

