from typing import *
from collections import *

def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, (op, *args) in enumerate(ops):
        if op == 'deposit':
            account, amount = args
            if account not in final_balances or amount <= 0:
                failed.append(i)
            else:
                final_balances[account] += amount
        elif op == 'withdraw':
            account, amount = args
            if account not in final_balances or amount <= 0 or final_balances[account] < amount:
                failed.append(i)
            else:
                final_balances[account] -= amount
        elif op == 'transfer':
            source, target, amount = args
            if source not in final_balances or target not in final_balances or amount <= 0 or final_balances[source] < amount + 2:
                failed.append(i)
            else:
                final_balances[source] -= amount + 2
                final_balances[target] += amount
        elif op == 'freeze':
            account = args[0]
            if account not in final_balances:
                failed.append(i)
            else:
                final_balances[account] = -final_balances[account]
        elif op == 'unfreeze':
            account = args[0]
            if account not in final_balances or final_balances[account] < 0:
                failed.append(i)
            else:
                final_balances[account] = -final_balances[account]
        else:
            failed.append(i)

    return final_balances, failed
