        elif op == 'transfer':
            if args[1] not in final_balances or args[2] not in final_balances:
                failed.append(i)
                continue
            if args[3] <= 0:
                failed.append(i)
                continue
            if final_balances[args[1]] < args[3] + 2:
                failed.append(i)
